package za.co.lepetse.admin;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.test.web.servlet.MockMvc;
import org.springframework.transaction.annotation.Transactional;
import com.fasterxml.jackson.databind.ObjectMapper;
import java.util.*;
import static org.springframework.security.test.web.servlet.request.SecurityMockMvcRequestPostProcessors.*;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
import static org.assertj.core.api.Assertions.*;
@SpringBootTest @AutoConfigureMockMvc @Transactional
@EnabledIfEnvironmentVariable(named="LEPETSE_DB_TEST",matches="true")
class AdminOpportunitiesTest {
 @Autowired MockMvc http;@Autowired JdbcTemplate db;@Autowired ObjectMapper json;
 Map<String,Object> details(){var d=new HashMap<String,Object>();for(String k:List.of("scope","rationale","requirements","briefing","submission","documents","source","instructions","phone"))d.put(k,"");d.putAll(Map.of("title","Stationery supply","buyer","TEST opportunity "+UUID.randomUUID(),"reference","TEST-1","closing","2099-12-01T09:00:00Z","recommendation","possible","contact","Buyer","email","buyer@example.invalid","buyerType","government"));return d;}
 long create(Map<String,Object> d)throws Exception{String response=http.perform(post("/api/admin/opportunities").with(user("owner").roles("ADMIN")).with(csrf()).contentType("application/json").content(json.writeValueAsString(Map.of("details",d)))).andExpect(status().isOk()).andReturn().getResponse().getContentAsString();return json.readTree(response).get("id").asLong();}
 @Test void pursueIsIdempotentAndLinksExistingRequestFlow()throws Exception{long id=create(details());long before=db.queryForObject("select count(*) from rfq",Long.class);for(int i=0;i<2;i++)http.perform(post("/api/admin/opportunities/"+id+"/pursue").with(user("owner").roles("ADMIN")).with(csrf()).contentType("application/json").content("{}")).andExpect(status().isOk());assertThat(db.queryForObject("select count(*) from rfq",Long.class)).isEqualTo(before+1);long rfq=db.queryForObject("select rfq_id from work_opportunity where id=?",Long.class,id);http.perform(get("/api/admin/rfqs/"+rfq).with(user("owner").roles("ADMIN"))).andExpect(status().isOk()).andExpect(jsonPath("$.opportunity.id").value(id)).andExpect(jsonPath("$.buyer.email").value("buyer@example.invalid")).andExpect(jsonPath("$.items.length()").value(0));}
 @Test void updatesFlagDeadlineAndPreserveDecisionAndRejectStaleEdits()throws Exception{var d=details();long id=create(d);http.perform(post("/api/admin/opportunities/"+id+"/progress").with(user("owner").roles("ADMIN")).with(csrf()).contentType("application/json").content("{\"progress\":\"dismissed\",\"version\":1}")).andExpect(status().isOk());d.put("closing","2099-12-02T09:00:00Z");String data=json.writeValueAsString(Map.of("details",d,"version",2));http.perform(put("/api/admin/opportunities/"+id).with(user("owner").roles("ADMIN")).with(csrf()).contentType("application/json").content(data)).andExpect(status().isOk()).andExpect(jsonPath("$.change_notice").value("Closing deadline changed")).andExpect(jsonPath("$.progress").value("dismissed"));http.perform(put("/api/admin/opportunities/"+id).with(user("owner").roles("ADMIN")).with(csrf()).contentType("application/json").content(data)).andExpect(status().isConflict());}
 @Test void preventsDuplicateNoticesAndRequiresContactBeforePursue()throws Exception{var d=details();d.put("email","");long id=create(d);http.perform(post("/api/admin/opportunities").with(user("owner").roles("ADMIN")).with(csrf()).contentType("application/json").content(json.writeValueAsString(Map.of("details",d)))).andExpect(status().isConflict());http.perform(post("/api/admin/opportunities/"+id+"/pursue").with(user("owner").roles("ADMIN")).with(csrf()).content("{}").contentType("application/json")).andExpect(status().isBadRequest());assertThat(db.queryForObject("select rfq_id from work_opportunity where id=?",Long.class,id)).isNull();}
 @Test void privateAndCsrfProtected()throws Exception{http.perform(get("/api/admin/opportunities")).andExpect(status().isUnauthorized());http.perform(get("/api/admin/opportunities").with(user("viewer").roles("USER"))).andExpect(status().isForbidden());http.perform(post("/api/admin/opportunities").with(user("owner").roles("ADMIN")).contentType("application/json").content(json.writeValueAsString(Map.of("details",details())))).andExpect(status().isForbidden());}
 @Test void savingAnOpportunityDoesNotCreateASourcingRequest()throws Exception{long id=create(details());long before=db.queryForObject("select count(*) from rfq",Long.class);http.perform(post("/api/admin/opportunities/"+id+"/progress").with(user("owner").roles("ADMIN")).with(csrf()).contentType("application/json").content("{\"progress\":\"saved\",\"version\":1}")).andExpect(status().isOk()).andExpect(jsonPath("$.progress").value("saved")).andExpect(jsonPath("$.rfq_id").doesNotExist());assertThat(db.queryForObject("select count(*) from rfq",Long.class)).isEqualTo(before);http.perform(post("/api/admin/opportunities/"+id+"/progress").with(user("owner").roles("ADMIN")).with(csrf()).contentType("application/json").content("{\"progress\":\"new\",\"version\":2}")).andExpect(status().isOk());}
}
